package com.example.domain.model.i18n

internal object DuaHi1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("नींद से जागने पर", "सारी तारीफ़ अल्लाह के लिए है जिसने हमें मौत (नींद) के बाद ज़िंदगी दी, और उसी की तरफ़ उठकर जाना है।", "नींद से जागते ही अल्लाह का शुक्र अदा करने के लिए।", "नबी ﷺ नींद से जागकर यह दुआ पढ़ते थे — दिन की शुरुआत शुक्र और आख़िरत की याद से।"),
        "dua_leaving_home" to DuaText("घर से निकलते वक़्त", "अल्लाह के नाम से; मैंने अल्लाह पर भरोसा किया। अल्लाह के बिना न कोई ताक़त है न कोई क़ुव्वत।", "घर से बाहर क़दम रखते वक़्त अल्लाह की हिफ़ाज़त के लिए।", "फ़रिश्ते कहते हैं: 'तुम्हें हिदायत दी गई, तुम्हारी किफ़ायत की गई और तुम्हें बचा लिया गया', और शैतान दूर हो जाता है।"),
        "dua_anxiety_distress" to DuaText("फ़िक्र और ग़म से राहत", "ऐ अल्लाह! मैं ग़म और फ़िक्र से, कमज़ोरी और सुस्ती से, कंजूसी और बुज़दिली से, क़र्ज़ के बोझ और लोगों के ग़लबे से तेरी पनाह माँगता हूँ।", "ग़म, फ़िक्र, क़र्ज़ के बोझ और ज़ेहनी परेशानी के वक़्त।", "नबी ﷺ यह दुआ कसरत से माँगते थे — ग़म, सुस्ती और क़र्ज़ की फ़िक्र से पनाह।"),
        "dua_sayyidul_istighfar" to DuaText("सय्यिदुल इस्तिग़फ़ार", "ऐ अल्लाह! तू ही मेरा रब है, तेरे सिवा कोई माबूद नहीं। तूने मुझे पैदा किया और मैं तेरा बंदा हूँ, और मैं अपनी ताक़त भर तेरे अहद और वादे पर क़ायम हूँ। मैं अपने किए के शर से तेरी पनाह माँगता हूँ। मैं अपने ऊपर तेरी नेमतों का और अपने गुनाहों का इक़रार करता हूँ, इसलिए मुझे माफ़ कर दे, क्योंकि तेरे सिवा कोई गुनाह माफ़ नहीं करता।", "सुबह और शाम — नबी ﷺ की सिखाई हुई तौबा की सबसे अफ़ज़ल दुआ।", "जो यक़ीन के साथ शाम को पढ़े और उसी रात मर जाए वह जन्नत में जाएगा; सुबह पढ़ने की भी यही फ़ज़ीलत है।"),
        "dua_parents" to DuaText("माँ-बाप के लिए दुआ", "ऐ मेरे रब! उन दोनों पर रहम फ़रमा जैसे उन्होंने बचपन में मुझे पाला।", "माँ-बाप के लिए क़ुरआनी दुआ — बचपन की परवरिश के बदले में।", "अल्लाह ने ख़ुद वालिदैन के लिए यह दुआ माँगने का हुक्म दिया।"),
        "dua_entering_mosque" to DuaText("मस्जिद में दाख़िल होना", "ऐ अल्लाह! मेरे लिए अपनी रहमत के दरवाज़े खोल दे।", "मस्जिद में दायाँ पाँव रखते वक़्त।", "नबी ﷺ ने मस्जिद में दाख़िल होते वक़्त यह दुआ पढ़ने की तालीम दी।"),
        "dua_morning_asbahna" to DuaText("सुबह का ज़िक्र", "हमने सुबह की और सारी बादशाहत ने अल्लाह के लिए सुबह की। सारी तारीफ़ अल्लाह के लिए है। अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं। उसी की बादशाहत है, उसी की तारीफ़ है और वह हर चीज़ पर क़ादिर है।", "सुबह के वक़्त पढ़ी जाने वाली मसनून दुआ।", "दिन की शुरुआत अल्लाह की बादशाहत और तौहीद के इक़रार से होती है।"),
        "dua_evening_amsayna" to DuaText("शाम का ज़िक्र", "हमने शाम की और सारी बादशाहत ने अल्लाह के लिए शाम की। सारी तारीफ़ अल्लाह के लिए है। अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं। उसी की बादशाहत है, उसी की तारीफ़ है और वह हर चीज़ पर क़ादिर है।", "शाम के वक़्त पढ़ी जाने वाली मसनून दुआ।", "रात की शुरुआत अल्लाह की बादशाहत और तौहीद के इक़रार से होती है।"),
        "dua_bismillah_la_yadurru" to DuaText("हर नुक़सान से हिफ़ाज़त", "अल्लाह के नाम से, जिसके नाम के साथ ज़मीन और आसमान में कोई चीज़ नुक़सान नहीं पहुँचा सकती, और वह सब कुछ सुनने वाला, जानने वाला है।", "सुबह और शाम तीन-तीन बार।", "जो इसे सुबह-शाम तीन बार पढ़े, उसे कोई चीज़ नुक़सान नहीं पहुँचाएगी।"),
        "dua_raditu_billahi" to DuaText("अल्लाह के रब होने पर राज़ी", "मैं अल्लाह के रब होने पर, इस्लाम के दीन होने पर और मुहम्मद ﷺ के नबी होने पर राज़ी हूँ।", "सुबह और शाम तीन बार।", "अल्लाह पर हक़ है कि क़यामत के दिन उसे राज़ी करे।"),
        "dua_hasbiyallah" to DuaText("हस्बियल्लाह (अल्लाह काफ़ी है)", "मुझे अल्लाह काफ़ी है, उसके सिवा कोई माबूद नहीं, उसी पर मैंने भरोसा किया और वह अर्श-ए-अज़ीम का रब है।", "सुबह और शाम सात बार।", "क़ुरआन की आयत; दुनिया और आख़िरत की फ़िक्रों में अल्लाह काफ़ी हो जाता है।"),
        "dua_subhanallah_wa_bihamdihi" to DuaText("सुब्हानल्लाहि व बिहम्दिही", "अल्लाह पाक है अपनी तारीफ़ के साथ।", "दिन में सौ बार।", "जो दिन में सौ बार कहे, उसके गुनाह माफ़ कर दिए जाते हैं चाहे समुंदर की झाग के बराबर हों।"),
        "dua_tahleel_100" to DuaText("ला इलाहा इल्लल्लाहु वहदहू", "अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं। उसी की बादशाहत और उसी की तारीफ़ है और वह हर चीज़ पर क़ादिर है।", "दिन में सौ बार पढ़ने की बड़ी फ़ज़ीलत।", "दस ग़ुलाम आज़ाद करने का सवाब, सौ नेकियाँ, सौ गुनाह माफ़, और शाम तक शैतान से हिफ़ाज़त।"),
        "dua_leaving_mosque" to DuaText("मस्जिद से निकलना", "ऐ अल्लाह! मैं तुझसे तेरा फ़ज़्ल माँगता हूँ।", "मस्जिद से बायाँ पाँव बाहर निकालते वक़्त।", "मस्जिद से निकलते हुए अल्लाह के फ़ज़्ल और रिज़्क़ की तलब।"),
        "dua_after_adhan" to DuaText("अज़ान के बाद", "ऐ अल्लाह! इस मुकम्मल पुकार और क़ायम होने वाली नमाज़ के रब! मुहम्मद ﷺ को वसीला और फ़ज़ीलत अता फ़रमा, और उन्हें उस मक़ाम-ए-महमूद पर पहुँचा जिसका तूने उनसे वादा किया है।", "अज़ान मुकम्मल होने के बाद।", "जो यह दुआ पढ़े, क़यामत के दिन उसके लिए नबी ﷺ की शफ़ाअत हलाल हो जाती है।"),
        "dua_after_salah_istighfar" to DuaText("फ़र्ज़ नमाज़ के बाद", "मैं अल्लाह से माफ़ी माँगता हूँ (3 बार)। ऐ अल्लाह! तू ही सलाम है और तुझ ही से सलामती है, तू बरकत वाला है ऐ जलाल और इकराम वाले।", "सलाम फेरने के फ़ौरन बाद।", "नबी ﷺ हर फ़र्ज़ नमाज़ के बाद यह पढ़ते थे।"),
        "dua_after_salah_help_dhikr" to DuaText("अपने ज़िक्र में मेरी मदद कर", "ऐ अल्लाह! अपने ज़िक्र, अपने शुक्र और अपनी अच्छी इबादत पर मेरी मदद फ़रमा।", "हर नमाज़ के बाद — नबी ﷺ ने हज़रत मुआज़ (रज़ि.) को वसीयत की।", "नबी ﷺ की ख़ास वसीयत — इबादत में ख़ूबी और इस्तिक़ामत।"),
        "dua_ayatul_kursi" to DuaText("नमाज़ के बाद आयतुल कुर्सी", "अल्लाह, उसके सिवा कोई माबूद नहीं, वह ज़िंदा है, सबको क़ायम रखने वाला। उसे न ऊँघ आती है न नींद। आसमानों और ज़मीन में जो कुछ है उसी का है। कौन है जो उसकी इजाज़त के बिना उसके पास सिफ़ारिश करे? वह जानता है जो उनके आगे और पीछे है, और लोग उसके इल्म में से किसी चीज़ का इहाता नहीं कर सकते मगर जितना वह चाहे। उसकी कुर्सी आसमानों और ज़मीन को घेरे हुए है, और उनकी हिफ़ाज़त उसे थकाती नहीं, और वह बुलंद, अज़मत वाला है।", "हर फ़र्ज़ नमाज़ के बाद और सोने से पहले।", "हर फ़र्ज़ नमाज़ के बाद पढ़ने वाले को जन्नत में जाने से सिर्फ़ मौत रोकती है; सोने से पहले पढ़ने पर सुबह तक हिफ़ाज़त।"),
        "dua_before_sleep" to DuaText("सोने से पहले", "ऐ अल्लाह! तेरे ही नाम के साथ मैं मरता (सोता) हूँ और जीता (जागता) हूँ।", "बिस्तर पर लेटने के बाद।", "नबी ﷺ सोने से पहले यह दुआ पढ़ते थे।"),
        "dua_sleep_tasbeeh" to DuaText("सोने से पहले तस्बीह-ए-फ़ातिमी", "अल्लाह पाक है (33), सारी तारीफ़ अल्लाह के लिए है (33), अल्लाह सबसे बड़ा है (34)।", "सोने से पहले — नबी ﷺ ने हज़रत फ़ातिमा और हज़रत अली (रज़ि.) को सिखाया।", "नबी ﷺ ने फ़रमाया यह तुम्हारे लिए ख़ादिम से बेहतर है।"),
        "dua_sleep_qina_adhab" to DuaText("अज़ाब से हिफ़ाज़त", "ऐ अल्लाह! मुझे उस दिन अपने अज़ाब से बचा जिस दिन तू अपने बंदों को उठाएगा।", "दायाँ हाथ गाल के नीचे रखकर, तीन बार।", "नींद को मौत की याद और आख़िरत की तैयारी बना देती है।"),
        "dua_bad_dream" to DuaText("बुरा ख़्वाब देखने पर", "मैं अल्लाह की पनाह माँगता हूँ मरदूद शैतान से।", "बुरा ख़्वाब देखने पर: बाईं तरफ़ तीन बार हल्का थुत्कार, फिर करवट बदलें।", "बुरा ख़्वाब नुक़सान नहीं देगा; किसी को बताएँ नहीं।"),
        "dua_yunus" to DuaText("हज़रत यूनुस (अ.) की दुआ", "तेरे सिवा कोई माबूद नहीं, तू पाक है, बेशक मैं ही ज़ालिमों में से था।", "मछली के पेट में हज़रत यूनुस (अ.) की दुआ — हर मुसीबत में।", "जो मुसलमान किसी भी मामले में यह दुआ करे, अल्लाह उसकी दुआ क़बूल फ़रमाता है।"),
        "dua_karb" to DuaText("सख़्त परेशानी के वक़्त की दुआ", "अल्लाह के सिवा कोई माबूद नहीं जो अज़मत वाला, बुर्दबार है। अल्लाह के सिवा कोई माबूद नहीं जो अर्श-ए-अज़ीम का रब है। अल्लाह के सिवा कोई माबूद नहीं जो आसमानों, ज़मीन और अर्श-ए-करीम का रब है।", "सख़्त परेशानी और तकलीफ़ के वक़्त।", "नबी ﷺ परेशानी के वक़्त यह दुआ पढ़ते थे।"),
        "dua_ya_hayyu_ya_qayyum" to DuaText("या हय्यु या क़य्यूम", "ऐ ज़िंदा, ऐ सबको क़ायम रखने वाले! तेरी रहमत के वास्ते से मैं फ़रियाद करता हूँ।", "जब कोई मामला बहुत भारी हो जाए।", "नबी ﷺ को जब कोई मामला परेशान करता तो यह पढ़ते।"),
        "dua_hasbunallah" to DuaText("हस्बुनल्लाहु व निअ्मल वकील", "हमें अल्लाह काफ़ी है और वह बेहतरीन कारसाज़ है।", "दुश्मन के ख़ौफ़ या बड़े ख़तरे के वक़्त।", "हज़रत इब्राहीम (अ.) ने आग में डाले जाते वक़्त और नबी ﷺ ने ख़तरे के वक़्त यह कहा।"),
        "dua_entering_home" to DuaText("घर में दाख़िल होना", "अल्लाह के नाम से।", "घर में दाख़िल होते वक़्त अल्लाह का नाम लें और सलाम करें।", "घर में दाख़िल होते और खाते वक़्त अल्लाह का ज़िक्र करने से शैतान कहता है: तुम्हारे लिए न यहाँ रात गुज़ारने की जगह है न खाना।"),
        "dua_travel" to DuaText("सफ़र (सवारी) की दुआ", "पाक है वह ज़ात जिसने इसे हमारे क़ाबू में कर दिया, वरना हम इसे क़ाबू में लाने वाले न थे, और बेशक हम अपने रब की तरफ़ लौटने वाले हैं।", "सवारी पर बैठकर तीन बार अल्लाहु अकबर के बाद।", "सफ़र की मसनून दुआ — हिफ़ाज़त और बरकत के लिए।"),
        "dua_entering_market" to DuaText("बाज़ार में दाख़िल होना", "अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं। उसी की बादशाहत और तारीफ़ है। वही ज़िंदा करता और मारता है, और वह ख़ुद ज़िंदा है, कभी नहीं मरेगा। उसी के हाथ में भलाई है और वह हर चीज़ पर क़ादिर है।", "बाज़ार में दाख़िल होते वक़्त।", "हदीस में इसकी बड़ी फ़ज़ीलत बयान हुई है (लाखों नेकियाँ)।"),
        "dua_adam_forgiveness" to DuaText("हज़रत आदम (अ.) की दुआ", "ऐ हमारे रब! हमने अपनी जानों पर ज़ुल्म किया, और अगर तू हमें माफ़ न करे और हम पर रहम न करे तो हम ज़रूर नुक़सान उठाने वालों में से हो जाएँगे।", "हज़रत आदम और हज़रत हव्वा (अ.) की तौबा की दुआ।", "इंसानियत की पहली तौबा — अल्लाह ने इसे क़बूल फ़रमाया।"),
        "dua_abu_bakr" to DuaText("हज़रत अबू बक्र (रज़ि.) को सिखाई गई दुआ", "ऐ अल्लाह! मैंने अपनी जान पर बहुत ज़ुल्म किया, और तेरे सिवा गुनाहों को कोई माफ़ नहीं करता, तो अपनी तरफ़ से मुझे माफ़ फ़रमा और मुझ पर रहम फ़रमा, बेशक तू ही बख़्शने वाला, रहम करने वाला है।", "नमाज़ में (तशह्हुद के बाद) पढ़ने के लिए नबी ﷺ ने हज़रत अबू बक्र सिद्दीक़ (रज़ि.) को सिखाई।", "नमाज़ के आख़िर में पढ़ने की मसनून दुआ।"),
        "dua_astaghfirullah_atubu" to DuaText("रोज़ाना इस्तिग़फ़ार", "मैं अल्लाह से माफ़ी माँगता हूँ और उसी की तरफ़ तौबा करता हूँ।", "नबी ﷺ दिन में सत्तर से ज़्यादा बार इस्तिग़फ़ार करते थे।", "नबी ﷺ ने फ़रमाया: मैं दिन में सत्तर से ज़्यादा बार अल्लाह से इस्तिग़फ़ार और तौबा करता हूँ।"),
        "dua_laylatul_qadr" to DuaText("शब-ए-क़द्र की दुआ", "ऐ अल्लाह! तू बहुत माफ़ करने वाला है, माफ़ी को पसंद करता है, तो मुझे माफ़ फ़रमा दे।", "हज़रत आइशा (रज़ि.) को शब-ए-क़द्र के लिए सिखाई गई।", "रमज़ान की आख़िरी रातों और शब-ए-क़द्र की ख़ास दुआ।"),
        "dua_family_coolness" to DuaText("आँखों की ठंडक (बीवी-बच्चे)", "ऐ हमारे रब! हमें हमारी बीवियों और औलाद से आँखों की ठंडक अता फ़रमा, और हमें परहेज़गारों का इमाम बना।", "नेक बीवी/शौहर और औलाद के लिए क़ुरआनी दुआ।", "घर में सुकून और नेक औलाद के लिए।"),
        "dua_righteous_children" to DuaText("नेक औलाद के लिए", "ऐ मेरे रब! मुझे अपने पास से पाकीज़ा औलाद अता फ़रमा, बेशक तू दुआ सुनने वाला है।", "हज़रत ज़करिया (अ.) की दुआ।", "औलाद की तलब के लिए क़ुरआनी दुआ।"),
        "dua_ibrahim_prayer_family" to DuaText("नमाज़ क़ायम करने वाले", "ऐ मेरे रब! मुझे और मेरी औलाद को नमाज़ क़ायम करने वाला बना। ऐ हमारे रब! मेरी दुआ क़बूल फ़रमा। ऐ हमारे रब! मुझे, मेरे वालिदैन को और सब मोमिनों को हिसाब के दिन बख़्श दे।", "हज़रत इब्राहीम (अ.) की अपने और औलाद के लिए दुआ।", "नमाज़ के आख़िर में आम तौर पर पढ़ी जाती है।"),
        "dua_newlywed" to DuaText("दूल्हा-दुल्हन को मुबारकबाद", "अल्लाह तुम्हारे लिए बरकत दे, तुम पर बरकत नाज़िल करे और तुम दोनों को भलाई में जमा रखे।", "निकाह करने वाले को मुबारकबाद देते वक़्त।", "निकाह की मसनून मुबारकबाद।"),
        "dua_before_eating" to DuaText("खाने से पहले", "अल्लाह के नाम से। (भूलने पर:) अल्लाह के नाम से, इसके शुरू और आख़िर में।", "खाने से पहले। भूल जाएँ तो बीच में पढ़ें।", "बिस्मिल्लाह पढ़ने से खाने में शैतान शरीक नहीं होता।"),
        "dua_after_eating" to DuaText("खाने के बाद", "सारी तारीफ़ अल्लाह के लिए जिसने मुझे यह खिलाया और मेरी किसी ताक़त और क़ुव्वत के बिना मुझे यह रिज़्क़ दिया।", "खाना ख़त्म करने के बाद।", "इसके पढ़ने वाले के पिछले गुनाह माफ़ कर दिए जाते हैं।"),
        "dua_host" to DuaText("मेज़बान के लिए", "ऐ अल्लाह! जो रिज़्क़ तूने उन्हें दिया है उसमें बरकत दे, उन्हें बख़्श दे और उन पर रहम फ़रमा।", "किसी के यहाँ खाना खाने के बाद मेज़बान के लिए।", "मेज़बान का शुक्रिया मसनून तरीक़े से।"),
        "dua_breaking_fast" to DuaText("रोज़ा खोलने पर", "प्यास चली गई, रगें तर हो गईं और अगर अल्लाह ने चाहा तो अज्र साबित हो गया।", "इफ़्तार के वक़्त।", "नबी ﷺ इफ़्तार के वक़्त यह फ़रमाते थे।"),
        "dua_new_clothes" to DuaText("नए कपड़े पहनना", "ऐ अल्लाह! तेरे ही लिए सारी तारीफ़ है, तूने ही मुझे यह पहनाया। मैं तुझसे इसकी भलाई और जिस काम के लिए यह बनाया गया उसकी भलाई माँगता हूँ, और इसके शर और जिस काम के लिए यह बनाया गया उसके शर से तेरी पनाह माँगता हूँ।", "नया कपड़ा पहनते वक़्त (कपड़े का नाम लेकर, जैसे क़मीज़ या इमामा)।", "नबी ﷺ नया कपड़ा पहनते तो यह दुआ फ़रमाते। (रोज़ाना कपड़े पहनने की दुआ 'कपड़े पहनना' में है।)"),
        "dua_rabbana_atina" to DuaText("दुनिया और आख़िरत की भलाई", "ऐ हमारे रब! हमें दुनिया में भी भलाई दे और आख़िरत में भी भलाई दे, और हमें आग के अज़ाब से बचा।", "नबी ﷺ सबसे ज़्यादा यह दुआ माँगते थे।", "दुनिया और आख़िरत की हर भलाई को जमा करने वाली दुआ।"),
        "dua_rabbi_zidni_ilma" to DuaText("इल्म में इज़ाफ़ा", "ऐ मेरे रब! मेरे इल्म में इज़ाफ़ा फ़रमा।", "इल्म में इज़ाफ़े के लिए।", "अल्लाह ने नबी ﷺ को सिर्फ़ इल्म में इज़ाफ़े की दुआ माँगने का हुक्म दिया।"),
        "dua_musa_sharh_sadr" to DuaText("सीना खुलने की दुआ (मूसा अ.)", "ऐ मेरे रब! मेरा सीना खोल दे, मेरा काम आसान कर दे, और मेरी ज़बान की गिरह खोल दे ताकि लोग मेरी बात समझ सकें।", "इम्तिहान, तक़रीर या किसी मुश्किल काम से पहले।", "हज़रत मूसा (अ.) की दुआ — दिल का इत्मीनान और काम में आसानी।"),
        "dua_la_tuzigh" to DuaText("दिल की साबित-क़दमी", "ऐ हमारे रब! हमें हिदायत देने के बाद हमारे दिलों को टेढ़ा न कर, और हमें अपने पास से रहमत अता फ़रमा, बेशक तू ही बहुत अता करने वाला है।", "हिदायत पर साबित-क़दमी के लिए।", "ईमान पर साबित रहने की दुआ।"),
        "dua_ya_muqallib" to DuaText("ऐ दिलों को फेरने वाले", "ऐ दिलों को फेरने वाले! मेरे दिल को अपने दीन पर साबित रख।", "नबी ﷺ अक्सर यह दुआ माँगते थे।", "हज़रत उम्मे सलमा (रज़ि.) के मुताबिक़ नबी ﷺ की सबसे ज़्यादा माँगी जाने वाली दुआ।"),
        "dua_la_tuakhidhna" to DuaText("सूरह बक़रह की आख़िरी आयतें", "ऐ हमारे रब! अगर हम भूल जाएँ या ग़लती करें तो हमारी पकड़ न फ़रमा। ऐ हमारे रब! हम पर ऐसा बोझ न डाल जैसा हमसे पहले लोगों पर डाला। ऐ हमारे रब! हम पर वह बोझ न डाल जिसकी हमें ताक़त नहीं। हमें माफ़ फ़रमा, बख़्श दे और हम पर रहम फ़रमा। तू ही हमारा मौला है, तो काफ़िर क़ौम के मुक़ाबले में हमारी मदद फ़रमा।", "रात को सोने से पहले — सूरह बक़रह की आख़िरी दो आयतें।", "जो रात को सूरह बक़रह की आख़िरी दो आयतें पढ़े, वह उसे काफ़ी हो जाती हैं।"),
        "dua_visiting_sick" to DuaText("बीमार की इयादत", "मैं अज़मत वाले अल्लाह से, जो अर्श-ए-अज़ीम का रब है, सवाल करता हूँ कि तुम्हें शिफ़ा दे।", "मरीज़ की इयादत के वक़्त सात बार।", "अगर मौत का वक़्त न आया हो तो अल्लाह उसे शिफ़ा दे देता है।"),
        "dua_ruqyah_pain" to DuaText("जिस्म के दर्द के लिए", "मैं अल्लाह और उसकी क़ुदरत की पनाह माँगता हूँ उस तकलीफ़ के शर से जो मैं महसूस करता हूँ और जिसका मुझे ख़ौफ़ है।", "दर्द की जगह हाथ रखकर तीन बार बिस्मिल्लाह, फिर सात बार यह दुआ।", "नबी ﷺ ने हज़रत उस्मान बिन अबिल-आस (रज़ि.) को दर्द के लिए सिखाई।"),
        "dua_ruqyah_nabawi" to DuaText("बीमार के लिए नबवी रुक़्या", "ऐ अल्लाह, लोगों के रब! तकलीफ़ दूर फ़रमा, शिफ़ा दे, तू ही शिफ़ा देने वाला है, तेरी शिफ़ा के सिवा कोई शिफ़ा नहीं, ऐसी शिफ़ा जो कोई बीमारी न छोड़े।", "मरीज़ पर हाथ फेरकर।", "नबी ﷺ अपने घर वालों की इयादत में यह पढ़ते थे।"),
        "dua_kalimat_tammat" to DuaText("मुकम्मल कलिमात की पनाह", "मैं अल्लाह के मुकम्मल कलिमात की पनाह माँगता हूँ हर उस चीज़ के शर से जो उसने पैदा की।", "किसी जगह पड़ाव करते वक़्त या शाम को।", "जो किसी जगह उतरकर यह पढ़े, वहाँ से जाने तक कोई चीज़ उसे नुक़सान नहीं देगी।"),
        "dua_evil_eye" to DuaText("बच्चों की हिफ़ाज़त (नज़र-ए-बद)", "मैं तुम दोनों को अल्लाह के मुकम्मल कलिमात की पनाह में देता हूँ हर शैतान और ज़हरीले जानवर से, और हर नुक़सान पहुँचाने वाली नज़र से।", "नबी ﷺ हज़रत हसन और हज़रत हुसैन (रज़ि.) पर यह दम करते थे।", "बच्चों को नज़र-ए-बद और शर से बचाने की मसनून दुआ (एक बच्चे के लिए 'उईज़ुका')।"),
        "dua_seeing_afflicted" to DuaText("किसी को मुसीबत में देखकर", "सारी तारीफ़ अल्लाह के लिए जिसने मुझे उससे आफ़ियत दी जिसमें तुम्हें मुब्तला किया, और मुझे अपनी बहुत सी मख़लूक़ पर फ़ज़ीलत दी।", "किसी को मुसीबत में देखकर (दिल में पढ़ें)।", "पढ़ने वाला उस मुसीबत से महफ़ूज़ रहता है।"),
        "dua_istikhara" to DuaText("सलातुल इस्तिख़ारा", "ऐ अल्लाह! मैं तेरे इल्म के ज़रिए तुझसे भलाई तलब करता हूँ, तेरी क़ुदरत के ज़रिए ताक़त माँगता हूँ, और तेरे बड़े फ़ज़्ल का सवाल करता हूँ। तू क़ुदरत रखता है मैं नहीं, तू जानता है मैं नहीं, और तू ग़ैब का ख़ूब जानने वाला है। ऐ अल्लाह! अगर तेरे इल्म में यह काम (अपना काम ज़ेहन में लाएँ) मेरे दीन, मेरी ज़िंदगी और अंजाम के लिए बेहतर है तो इसे मेरे लिए मुक़द्दर कर, आसान कर और फिर उसमें बरकत दे। और अगर तेरे इल्म में यह काम मेरे दीन, ज़िंदगी और अंजाम के लिए बुरा है तो इसे मुझसे और मुझे इससे फेर दे, और मेरे लिए भलाई मुक़द्दर कर जहाँ भी हो, फिर मुझे उस पर राज़ी कर दे।", "किसी जायज़ काम में भलाई तलब करने के लिए दो रकअत नफ़्ल के बाद।", "नबी ﷺ सहाबा को हर काम में इस्तिख़ारा ऐसे सिखाते जैसे क़ुरआन की सूरत।"),
        "dua_allahumma_bika_asbahna" to DuaText("अल्लाहुम्मा बिका असबहना", "ऐ अल्लाह! तेरी ही मदद से हमने सुबह की और तेरी ही मदद से शाम की, तेरे ही हुक्म से जीते और मरते हैं, और तेरी ही तरफ़ उठकर जाना है।", "सुबह के वक़्त।", "नबी ﷺ सहाबा को सुबह-शाम यह सिखाते थे।"),
        "dua_allahumma_bika_amsayna" to DuaText("अल्लाहुम्मा बिका अमसैना", "ऐ अल्लाह! तेरी ही मदद से हमने शाम की और तेरी ही मदद से सुबह की, तेरे ही हुक्म से जीते और मरते हैं, और तेरी ही तरफ़ लौटना है।", "शाम के वक़्त।", "नबी ﷺ सहाबा को सुबह-शाम यह सिखाते थे।"),
        "dua_afiyah_morning" to DuaText("आफ़ियत की दुआ", "ऐ अल्लाह! मैं तुझसे दुनिया और आख़िरत में माफ़ी और आफ़ियत माँगता हूँ।", "नबी ﷺ सुबह-शाम यह दुआ कभी नहीं छोड़ते थे।", "आफ़ियत से बेहतर कोई चीज़ किसी को नहीं दी गई।"),
        "dua_afini_fi_badani" to DuaText("जिस्म, सुनने और देखने की सेहत", "ऐ अल्लाह! मेरे जिस्म में आफ़ियत दे, मेरी सुनने की ताक़त में आफ़ियत दे, मेरी नज़र में आफ़ियत दे। तेरे सिवा कोई माबूद नहीं।", "सुबह और शाम तीन-तीन बार।", "सेहत और हवास की हिफ़ाज़त की दुआ।"),
        "dua_ya_hayyu_aslih" to DuaText("मेरे सारे काम दुरुस्त कर दे", "ऐ ज़िंदा, ऐ क़ायम रखने वाले! तेरी रहमत से फ़रियाद करता हूँ, मेरे सारे काम दुरुस्त कर दे और मुझे पलक झपकने के बराबर भी मेरे नफ़्स के हवाले न कर।", "नबी ﷺ ने हज़रत फ़ातिमा (रज़ि.) को सुबह-शाम पढ़ने की वसीयत की।", "हर काम में अल्लाह की मदद की तलब।"),
        "dua_subhanallah_adada_khalqihi" to DuaText("हज़रत जुवैरिया (रज़ि.) की तस्बीह", "अल्लाह पाक है अपनी तारीफ़ के साथ — अपनी मख़लूक़ की गिनती के बराबर, अपनी रज़ा के मुताबिक़, अपने अर्श के वज़न के बराबर और अपने कलिमात की स्याही के बराबर।", "सुबह तीन बार — घंटों के ज़िक्र से भारी।", "यह चार कलिमात तीन बार कहना सुबह से दोपहर तक के ज़िक्र से वज़न में भारी हैं।"),
        "dua_salawat" to DuaText("दुरूद-ए-इब्राहीमी", "ऐ अल्लाह! मुहम्मद ﷺ और आल-ए-मुहम्मद पर रहमत नाज़िल फ़रमा जैसे तूने इब्राहीम (अ.) और आल-ए-इब्राहीम पर नाज़िल की, बेशक तू तारीफ़ वाला, बुज़ुर्गी वाला है। ऐ अल्लाह! मुहम्मद ﷺ और आल-ए-मुहम्मद पर बरकत नाज़िल फ़रमा जैसे तूने इब्राहीम (अ.) और आल-ए-इब्राहीम पर नाज़िल की, बेशक तू तारीफ़ वाला, बुज़ुर्गी वाला है।", "नमाज़ में और हर वक़्त नबी ﷺ पर दुरूद।", "जो एक बार दुरूद भेजे, अल्लाह उस पर दस रहमतें नाज़िल फ़रमाता है (मुस्लिम 408)।"),
        "dua_wudu_after" to DuaText("वुज़ू के बाद", "मैं गवाही देता हूँ कि अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं, और मुहम्मद ﷺ उसके बंदे और रसूल हैं। ऐ अल्लाह! मुझे तौबा करने वालों और पाक रहने वालों में से बना।", "वुज़ू मुकम्मल करने के बाद।", "जन्नत के आठों दरवाज़े खोल दिए जाते हैं, जिससे चाहे दाख़िल हो।"),
        "dua_wudu_before" to DuaText("वुज़ू से पहले", "अल्लाह के नाम से।", "वुज़ू शुरू करते वक़्त।", "जिसने वुज़ू पर अल्लाह का नाम न लिया उसका वुज़ू (कामिल) नहीं।"),
        "dua_istiftah" to DuaText("सना (नमाज़ की शुरुआती दुआ)", "ऐ अल्लाह! तू पाक है अपनी तारीफ़ के साथ, तेरा नाम बरकत वाला है, तेरी शान बुलंद है और तेरे सिवा कोई माबूद नहीं।", "नमाज़ शुरू करने पर, तकबीर-ए-तहरीमा के फ़ौरन बाद।", "नमाज़ की मसनून शुरुआती दुआ।"),
        "dua_ruku" to DuaText("रुकू में", "पाक है मेरा रब जो अज़मत वाला है।", "रुकू में कम से कम तीन बार।", "रुकू की मसनून तस्बीह।"),
        "dua_sujood" to DuaText("सज्दे में", "पाक है मेरा रब जो सबसे बुलंद है।", "सज्दे में कम से कम तीन बार।", "बंदा सज्दे में अपने रब के सबसे क़रीब होता है (मुस्लिम 482)।"),
        "dua_rising_ruku" to DuaText("रुकू से उठते वक़्त", "अल्लाह ने उसकी सुन ली जिसने उसकी तारीफ़ की। ऐ हमारे रब! तेरे ही लिए सारी तारीफ़ है।", "रुकू से उठते हुए और सीधे खड़े होकर।", "जिसका 'रब्बना व लकल-हम्द' फ़रिश्तों के साथ मिल गया उसके पिछले गुनाह माफ़।"),
        "dua_between_sajdas" to DuaText("दो सज्दों के बीच", "ऐ मेरे रब! मुझे बख़्श दे, ऐ मेरे रब! मुझे बख़्श दे।", "दो सज्दों के दरमियान बैठे हुए।", "जलसे की मसनून दुआ।"),
        "dua_before_salam_four" to DuaText("चार चीज़ों से पनाह (सलाम से पहले)", "ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ जहन्नम के अज़ाब से, क़ब्र के अज़ाब से, ज़िंदगी और मौत के फ़ितने से, और मसीह दज्जाल के फ़ितने के शर से।", "आख़िरी तशह्हुद और दुरूद के बाद, सलाम से पहले।", "नबी ﷺ ने इन चार चीज़ों से पनाह माँगने का हुक्म दिया।"),
        "dua_qunoot_witr" to DuaText("वित्र में क़ुनूत", "ऐ अल्लाह! मुझे हिदायत दे उन लोगों में जिन्हें तूने हिदायत दी, आफ़ियत दे उनमें जिन्हें तूने आफ़ियत दी, मेरी सरपरस्ती कर उनमें जिनकी तूने सरपरस्ती की, जो तूने दिया उसमें बरकत दे, और जो तूने फ़ैसला किया उसके शर से बचा। बेशक तू फ़ैसला करता है और तेरे ख़िलाफ़ फ़ैसला नहीं होता, और जिसका तू दोस्त हो वह ज़लील नहीं होता। ऐ हमारे रब! तू बरकत वाला और बुलंद है।", "वित्र की नमाज़ में — नबी ﷺ ने हज़रत हसन बिन अली (रज़ि.) को सिखाई।", "वित्र की मसनून क़ुनूत। (अहनाफ़ के यहाँ 'अल्लाहुम्मा इन्ना नस्तईनुका' भी मशहूर है।)"),
        "dua_qunoot_hanafi" to DuaText("क़ुनूत (अल्लाहुम्मा इन्ना नस्तईनुका)", "ऐ अल्लाह! हम तुझसे मदद और माफ़ी माँगते हैं, तुझ पर ईमान लाते और भरोसा करते हैं, तेरी अच्छी तारीफ़ करते हैं, तेरा शुक्र करते हैं, नाशुक्री नहीं करते, और जो तेरी नाफ़रमानी करे उसे छोड़ते हैं। ऐ अल्लाह! हम तेरी ही इबादत करते हैं, तेरे ही लिए नमाज़ पढ़ते और सज्दा करते हैं, तेरी तरफ़ दौड़ते और लपकते हैं, तेरी रहमत के उम्मीदवार हैं और तेरे अज़ाब से डरते हैं; बेशक तेरा अज़ाब काफ़िरों को पहुँचने वाला है।", "वित्र में — अहनाफ़ का मामूल।", "हज़रत उमर (रज़ि.) से क़ुनूत में मनक़ूल।"),
        "dua_sleep_aslamtu" to DuaText("सोने से पहले आख़िरी बात", "ऐ अल्लाह! मैंने अपनी जान तेरे सुपुर्द की, अपना मामला तेरे हवाले किया, अपनी पीठ तेरी पनाह में दी, तेरी रग़बत और तेरे ख़ौफ़ के साथ। तुझसे बचने की कोई जगह और नजात नहीं मगर तेरी ही तरफ़। मैं तेरी नाज़िल की हुई किताब और तेरे भेजे हुए नबी पर ईमान लाया।", "वुज़ू करके दाईं करवट पर लेटकर — सबसे आख़िरी बात।", "अगर उसी रात मौत आ जाए तो फ़ितरत (इस्लाम) पर मौत होगी।"),
        "dua_waking_night" to DuaText("रात को आँख खुलने पर", "अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं, उसी की बादशाहत और तारीफ़ है और वह हर चीज़ पर क़ादिर है। सारी तारीफ़ अल्लाह के लिए, अल्लाह पाक है, अल्लाह के सिवा कोई माबूद नहीं, अल्लाह सबसे बड़ा है, और अल्लाह के बिना न कोई ताक़त है न क़ुव्वत। ऐ अल्लाह! मुझे बख़्श दे।", "रात को आँख खुलने पर।", "दुआ क़बूल होती है, और वुज़ू करके नमाज़ पढ़े तो नमाज़ क़बूल होती है।"),
        "dua_hamm_ibn_masud" to DuaText("ग़म की दुआ (इब्न मसऊद)", "ऐ अल्लाह! मैं तेरा बंदा हूँ, तेरे बंदे का बेटा, तेरी बंदी का बेटा। मेरी पेशानी तेरे हाथ में है, मुझ पर तेरा हुक्म जारी है, मेरे बारे में तेरा फ़ैसला इंसाफ़ वाला है। मैं तुझसे तेरे हर उस नाम के वास्ते से सवाल करता हूँ जो तूने अपना रखा, या अपनी किताब में उतारा, या अपनी किसी मख़लूक़ को सिखाया, या अपने पास इल्म-ए-ग़ैब में महफ़ूज़ रखा — कि क़ुरआन को मेरे दिल की बहार, मेरे सीने का नूर, मेरे ग़म का इलाज और मेरी फ़िक्र को दूर करने वाला बना दे।", "ग़म और परेशानी में — अल्लाह ग़म को ख़ुशी से बदल देता है।", "अल्लाह उसकी फ़िक्र और ग़म दूर करके ख़ुशी अता फ़रमाता है।"),
        "dua_difficulty_sahl" to DuaText("जब कोई काम मुश्किल हो", "ऐ अल्लाह! कोई चीज़ आसान नहीं मगर जिसे तू आसान कर दे, और तू जब चाहे मुश्किल को आसान कर देता है।", "कोई काम मुश्किल लगे तो।", "इम्तिहान और मुश्किल कामों में आसानी।"),
        "dua_musibah" to DuaText("मुसीबत पर (इस्तिरजा)", "हम अल्लाह ही के हैं और उसी की तरफ़ लौटने वाले हैं। ऐ अल्लाह! मुझे मेरी मुसीबत में अज्र दे और मुझे इससे बेहतर बदला अता फ़रमा।", "किसी भी नुक़सान या मुसीबत पर।", "अल्लाह ज़रूर बेहतर बदला देता है — हज़रत उम्मे सलमा (रज़ि.) को नबी ﷺ मिले।"),
        "dua_debt" to DuaText("क़र्ज़ से छुटकारे के लिए", "ऐ अल्लाह! अपने हलाल के ज़रिए मुझे हराम से बचाकर काफ़ी हो जा, और अपने फ़ज़्ल से मुझे अपने सिवा सबसे बेनियाज़ कर दे।", "क़र्ज़ की अदायगी के लिए — हज़रत अली (रज़ि.) ने सिखाई।", "पहाड़ के बराबर क़र्ज़ हो तो भी अल्लाह अदा करवा देता है।"),
        "dua_anger" to DuaText("ग़ुस्से के वक़्त", "मैं अल्लाह की पनाह माँगता हूँ मरदूद शैतान से।", "ग़ुस्सा आने पर।", "नबी ﷺ ने फ़रमाया: अगर यह कह ले तो उसका ग़ुस्सा चला जाए।"),
        "dua_waswasa" to DuaText("ईमान में वसवसे के ख़िलाफ़", "मैं अल्लाह और उसके रसूलों पर ईमान लाया।", "ईमान के बारे में शैतानी वसवसे आएँ तो।", "वसवसा आए तो यह कहे और रुक जाए (अऊज़ु बिल्लाह भी पढ़े)।"),
        "dua_travel_full" to DuaText("सफ़र की मुकम्मल दुआ", "ऐ अल्लाह! हम इस सफ़र में तुझसे नेकी और तक़वा माँगते हैं और ऐसा अमल जिसे तू पसंद करे। ऐ अल्लाह! हमारा यह सफ़र हम पर आसान कर दे और इसकी दूरी को समेट दे। ऐ अल्लाह! तू ही सफ़र में साथी और घर वालों में निगहबान है।", "सफ़र पर रवाना होते वक़्त, 'सुब्हानल्लज़ी सख़्ख़रा' के बाद।", "सफ़र की मुकम्मल मसनून दुआ।"),
        "dua_return_travel" to DuaText("सफ़र से वापसी", "हम लौटने वाले, तौबा करने वाले, इबादत करने वाले और अपने रब की तारीफ़ करने वाले हैं।", "सफ़र से वापसी पर।", "नबी ﷺ सफ़र से वापसी पर यह फ़रमाते थे।"),
        "dua_farewell_traveller" to DuaText("मुसाफ़िर को रुख़्सत करना", "मैं तुम्हारा दीन, तुम्हारी अमानत और तुम्हारे आमाल का अंजाम अल्लाह के सुपुर्द करता हूँ।", "मुसाफ़िर को रुख़्सत करते वक़्त।", "अल्लाह के सुपुर्द की हुई चीज़ ज़ाया नहीं होती।"),
        "dua_entering_town" to DuaText("किसी जगह ठहरना", "मैं अल्लाह के मुकम्मल कलिमात की पनाह माँगता हूँ हर मख़लूक़ के शर से।", "किसी जगह पड़ाव या नए शहर में पहुँचकर।", "वहाँ से कूच करने तक कोई चीज़ नुक़सान नहीं देगी।"),
        "dua_boarding_ship" to DuaText("कश्ती/सवारी पर सवार होना", "अल्लाह ही के नाम से इसका चलना और ठहरना है, बेशक मेरा रब बख़्शने वाला, रहम करने वाला है।", "कश्ती या सवारी पर सवार होते वक़्त — हज़रत नूह (अ.) का क़ौल।", "क़ुरआनी आयत — नूह (अ.) की कश्ती की दुआ।"),
        "dua_istighfar_hayyul_qayyum" to DuaText("हय्युल क़य्यूम के साथ इस्तिग़फ़ार", "मैं उस अल्लाह से माफ़ी माँगता हूँ जिसके सिवा कोई माबूद नहीं, जो ज़िंदा और क़ायम रखने वाला है, और उसी की तरफ़ तौबा करता हूँ।", "तौबा के लिए।", "गुनाह माफ़ हो जाते हैं चाहे मैदान-ए-जंग से भागा हो।"),
        "dua_rabbighfir_warham" to DuaText("रब्बिग़फ़िर वरहम", "ऐ मेरे रब! बख़्श दे और रहम फ़रमा, और तू सबसे बेहतर रहम करने वाला है।", "क़ुरआनी दुआ — मग़फ़िरत और रहमत।", "सूरह मोमिनून की आख़िरी आयत।"),
        "dua_majlis_kaffarah" to DuaText("कफ़्फ़ारा-ए-मजलिस", "ऐ अल्लाह! तू पाक है अपनी तारीफ़ के साथ। मैं गवाही देता हूँ कि तेरे सिवा कोई माबूद नहीं। मैं तुझसे माफ़ी माँगता हूँ और तेरी तरफ़ तौबा करता हूँ।", "मजलिस/बैठक से उठते वक़्त।", "मजलिस में जो ग़लत बातें हुईं उनका कफ़्फ़ारा बन जाती है।"),
        "dua_jami_forgiveness" to DuaText("जामे मग़फ़िरत", "ऐ अल्लाह! मेरी ग़लती, मेरी नादानी, मेरे काम में मेरी ज़्यादती, और वह सब जो तू मुझसे ज़्यादा जानता है, माफ़ फ़रमा दे।", "नबी ﷺ की जामे दुआ।", "नबी ﷺ यह दुआ माँगा करते थे।"),
        "dua_parents_nuh" to DuaText("वालिदैन के लिए हज़रत नूह (अ.) की दुआ", "ऐ मेरे रब! मुझे, मेरे वालिदैन को, जो ईमान की हालत में मेरे घर में दाख़िल हो उसको, और सब मोमिन मर्दों और औरतों को बख़्श दे।", "वालिदैन और मोमिनों के लिए।", "हज़रत नूह (अ.) की दुआ।"),
        "dua_shukr_parents" to DuaText("वालिदैन की नेमत का शुक्र और नेक औलाद", "ऐ मेरे रब! मुझे तौफ़ीक़ दे कि मैं तेरी उस नेमत का शुक्र अदा करूँ जो तूने मुझ पर और मेरे वालिदैन पर की, और ऐसे नेक अमल करूँ जिन्हें तू पसंद करे, और मेरी औलाद को भी नेक बना दे। मैं तेरी तरफ़ तौबा करता हूँ और मैं फ़रमाँबरदारों में से हूँ।", "चालीस साल की उम्र की क़ुरआनी दुआ।", "शुक्र, नेक अमल और औलाद की इस्लाह — सब एक दुआ में।"),
        "dua_intimacy" to DuaText("मियाँ-बीवी के मिलाप से पहले", "अल्लाह के नाम से। ऐ अल्लाह! हमें शैतान से दूर रख और जो (औलाद) तू हमें दे उसे भी शैतान से दूर रख।", "मियाँ-बीवी के मिलाप से पहले।", "अगर औलाद मुक़द्दर हो तो शैतान उसे कभी नुक़सान नहीं पहुँचाएगा।"),
        "dua_ibrahim_children_protection" to DuaText("घर और औलाद की हिफ़ाज़त", "ऐ मेरे रब! इस शहर को अमन वाला बना दे और मुझे और मेरी औलाद को बुतों की इबादत से बचा।", "हज़रत इब्राहीम (अ.) की दुआ — शहर और औलाद की हिफ़ाज़त।", "तौहीद पर क़ायम रहने की दुआ।"),
        "dua_drinking_milk" to DuaText("दूध पीते वक़्त", "ऐ अल्लाह! हमारे लिए इसमें बरकत दे और हमें और ज़्यादा अता फ़रमा।", "दूध पीने पर।", "दूध खाने और पीने दोनों की जगह काफ़ी होता है।"),
        "dua_iftar_host" to DuaText("किसी के यहाँ इफ़्तार करने पर", "तुम्हारे यहाँ रोज़ेदार इफ़्तार करें, नेक लोग तुम्हारा खाना खाएँ और फ़रिश्ते तुम्हारे लिए दुआ करें।", "किसी के यहाँ इफ़्तार करने पर।", "नबी ﷺ की मेज़बान के लिए दुआ।"),
        "dua_seeing_first_fruit" to DuaText("पहला फल देखकर", "ऐ अल्लाह! हमारे फलों में, हमारे शहर में, हमारे साअ और हमारे मुद्द (नाप-तौल) में बरकत दे।", "मौसम का पहला फल देखकर।", "रिज़्क़ और शहर में बरकत की दुआ।"),
        "dua_good_news" to DuaText("ख़ुशख़बरी मिलने पर", "सारी तारीफ़ उस अल्लाह के लिए जिसकी नेमत से अच्छे काम मुकम्मल होते हैं।", "ख़ुशी की ख़बर मिलने पर (और सज्दा-ए-शुक्र)।", "नबी ﷺ पसंदीदा चीज़ देखकर यह फ़रमाते।"),
        "dua_looking_mirror" to DuaText("आईना देखते वक़्त", "ऐ अल्लाह! जैसे तूने मेरी सूरत अच्छी बनाई, वैसे ही मेरे अख़लाक़ भी अच्छे बना दे।", "आईना देखते वक़्त।", "नबी ﷺ यह दुआ फ़रमाते थे (आईने की क़ैद के बिना भी साबित है)।"),
        "dua_rabbana_taqabbal" to DuaText("आमाल की क़बूलियत", "ऐ हमारे रब! हमसे क़बूल फ़रमा, बेशक तू सुनने वाला, जानने वाला है। और हमारी तौबा क़बूल फ़रमा, बेशक तू तौबा क़बूल करने वाला, रहम करने वाला है।", "हज़रत इब्राहीम और इस्माईल (अ.) ने काबा की तामीर के वक़्त माँगी।", "हर नेक अमल के बाद क़बूलियत की दुआ।"),
    )
}
